changeSet.sql:
if not exists (select * from sys.indexes where name = 'IX_Intersect_Uid')
begin
	create unique nonclustered index [IX_Intersect_Uid] on [dbo].[Intersect] ([uid] asc)
end

if exists (select * from sys.indexes where name = 'CIX_Intersect')
begin
	drop index [CIX_Intersect] on [dbo].[Intersect] with ( ONLINE = ON );
	alter table [dbo].[Intersect] drop constraint PK_Intersect;
	alter table [dbo].[Intersect] add constraint [PK_Intersect] primary key clustered ( [ID] asc ) on [PRIMARY];
end

if not exists (select * from sys.indexes where name = 'IX_Intersect_IntersectTypeID')
begin
	create nonclustered index [IX_Intersect_IntersectTypeID] on [dbo].[Intersect] ( [IntersectTypeID] ASC )
end

if not exists (select * from sys.indexes where name = 'IX_Intersect_Object_IntersectType_Deleted')
begin
	create nonclustered index [IX_Intersect_Object_IntersectType_Deleted] on [dbo].[Intersect] ( [Object] ASC, [ObjectID] ASC, [IntersectTypeID] ASC, [Deleted] ASC ) INCLUDE([ID]) 
end

if not exists (select * from sys.indexes where name = 'IX_Intersect_Subject_SubjectID_IntersectType')
begin
	create nonclustered index [IX_Intersect_Subject_SubjectID_IntersectType] on [dbo].[Intersect] ( [SubjectID] ASC, [Subject] ASC ) INCLUDE([IntersectTypeID]) 
end

if not exists (select * from sys.indexes where name = 'IX_Intersect_Object_ObjectID_IntersectType')
begin
	create nonclustered index [IX_Intersect_Object_ObjectID_IntersectType] on [dbo].[Intersect] ( [ObjectID] asc, [Object] asc ) include ( [IntersectTypeID] ) 
end

if not exists (select * from sys.indexes where name = 'IX_Intersect_SubjectAssetID_IntersectType')
begin
	create nonclustered index [IX_Intersect_SubjectAssetID_IntersectType] on [dbo].[Intersect] ( SubjectAssetID asc ) include ( [IntersectTypeID] ) 
end

if not exists (select * from sys.indexes where name = 'IX_Intersect_SubjectAssetTypeID_IntersectType')
begin
	create nonclustered index [IX_Intersect_SubjectAssetTypeID_IntersectType] on [dbo].[Intersect] ( SubjectAssetTypeID asc ) include ( [IntersectTypeID] ) 
end

if not exists (select * from sys.indexes where name = 'IX_Intersect_ObjectAssetID_IntersectType')
begin
	create nonclustered index [IX_Intersect_ObjectAssetID_IntersectType] on [dbo].[Intersect] ( ObjectAssetID asc ) include ( [IntersectTypeID] ) 
end

if not exists (select * from sys.indexes where name = 'IX_Intersect_ObjectAssetTypeID_IntersectType')
begin
	create nonclustered index [IX_Intersect_ObjectAssetTypeID_IntersectType] on [dbo].[Intersect] ( ObjectAssetTypeID asc ) include ( [IntersectTypeID] ) 
end

CREATE OR ALTER TRIGGER [dbo].[Intersect_AfterInsert] ON [dbo].[Intersect] FOR INSERT AS BEGIN SET NOCOUNT ON;
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID], [AssetID]) select 'Add', [queue].WriteIndexXml('', I.Subject, I.SubjectID, I.UpdatedBy), 'Intersect', I.ID, ISNULL(A.ID, 0) as AssetID from inserted I left outer join [dbo].[Asset] A on I.[Subject] = A.[Object] and I.[SubjectID] = a.[ObjectID];
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID], [AssetID]) select 'Add', [queue].WriteIndexXml('', I.Object, I.ObjectID, I.UpdatedBy), 'Intersect', I.ID, ISNULL(A.ID, 0) as AssetID from inserted I left outer join [dbo].[Asset] A on I.[Object] = A.[Object] and I.[ObjectID] = a.[ObjectID]; END

CREATE OR ALTER TRIGGER [dbo].[Intersect_AfterUpdate] ON [dbo].[Intersect] FOR UPDATE AS BEGIN SET NOCOUNT ON;
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID], [AssetID]) select 'Update', [queue].WriteIndexXml('', I.Subject, I.SubjectID, I.UpdatedBy), 'Intersect', I.ID, ISNULL(A.ID, 0) as AssetID from inserted I left outer join [dbo].[Asset] A on I.[Subject] = A.[Object] and I.[SubjectID] = a.[ObjectID];
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID], [AssetID]) select 'Update', [queue].WriteIndexXml('', I.Object, I.ObjectID, I.UpdatedBy), 'Intersect', I.ID, ISNULL(A.ID, 0) as AssetID from inserted I left outer join [dbo].[Asset] A on I.[Object] = A.[Object] and I.[ObjectID] = a.[ObjectID]; END
